    gl.deleteTexture(strength0);
    gl.deleteTexture(strength1);
    gl.deleteTexture(label0);
    gl.deleteTexture(label1);
    gl.bindVertexArray(this.unusedVAO);
    gl.viewport(0, 0, gl.canvas.width, gl.canvas.height);
