    const dy = this.back.dims[2];
    const dz = this.back.dims[3];
    x = Math.min(Math.max(x, 0), dx - 1);
    y = Math.min(Math.max(y, 0), dy - 1);
    z = Math.min(Math.max(z, 0), dz - 1);
